// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != c.owner());
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));
        vm.prank(caller);
        bool ok = true;
        try c.setOwner(newOwner) { } catch { ok = false; }
        assertTrue(caller == c.owner() || !ok);
    }
}
